choose.when:
SELECT COUNT(*) FROM public.skill_effects e
JOIN public.skills s ON s.game_id = e.game_id AND s.skill_key = e.skill_key
WHERE e.game_id = #{gameId} AND e.skill_key = #{sourceParentKey} AND e.effect_key = #{sourceKey}

mapper.select:
SELECT image_key FROM public.image_relations
WHERE game_id = #{gameId} AND source_type = #{sourceType}
  AND source_parent_key = #{sourceParentKey} AND source_key = #{sourceKey}

mapper.delete:
DELETE FROM public.image_relations
WHERE game_id = #{gameId} AND source_type = #{sourceType}
  AND source_parent_key = #{sourceParentKey} AND source_key = #{sourceKey}
